const linhas = $input.all().map(item => {
  const s = item.json;
  return `- ${s.servico}: R$ ${s.preco} (${s.duracao_minutos} min)`;
});
return [{ json: { lista_servicos: linhas.join('\n') } }];

const ZONA = 'America/Sao_Paulo';
const ABERTURA = 9;
const FECHAMENTO = 18;
const DIAS = 14;
const ANTECEDENCIA_MINUTOS = 60;

const agora = DateTime.now().setZone(ZONA);
const eventos = $input.all().map(i => i.json);

// Se a busca no Calendar falhou, o node devolve { error } — não dá pra sugerir nada com segurança.
const agendaConsultada = !eventos.some(e => e.error);

// Mesmo critério do Verificar Disponibilidade (free/busy): ignora cancelados e eventos marcados como "livre".
const ocupados = eventos
  .filter(e => e.start && e.status !== 'cancelled' && e.transparency !== 'transparent')
  .map(e => ({
    inicio: e.start.dateTime ? DateTime.fromISO(e.start.dateTime).setZone(ZONA) : DateTime.fromISO(e.start.date, { zone: ZONA }).startOf('day'),
    fim: e.end.dateTime ? DateTime.fromISO(e.end.dateTime).setZone(ZONA) : DateTime.fromISO(e.end.date, { zone: ZONA }).startOf('day')
  }))
  .filter(o => o.inicio.isValid && o.fim.isValid);

const duracoes = $('Buscar Serviços e Preços').all().map(i => Number(i.json.duracao_minutos)).filter(Boolean);
const menorDuracao = duracoes.length ? Math.min(...duracoes) : 30;

// Primeiro início aceitável: agora + antecedência, arredondado pra cima em múltiplos de 30 min.
let inicioMinimo = agora.plus({ minutes: ANTECEDENCIA_MINUTOS }).startOf('minute');
const resto = inicioMinimo.minute % 30;
if (resto) inicioMinimo = inicioMinimo.plus({ minutes: 30 - resto });

const hora = dt => dt.toFormat('HH:mm');
const linhas = [];

for (let d = 0; d < DIAS; d++) {
  const dia = agora.startOf('day').plus({ days: d });
  if (dia.weekday === 7) continue;

  const fechamento = dia.set({ hour: FECHAMENTO, minute: 0 });
  let cursor = DateTime.max(dia.set({ hour: ABERTURA, minute: 0 }), inicioMinimo);
  if (cursor >= fechamento) continue;

  const doDia = ocupados
    .filter(o => o.inicio < fechamento && o.fim > cursor)
    .sort((a, b) => a.inicio - b.inicio);

  const janelas = [];
  for (const o of doDia) {
    if (o.inicio > cursor) janelas.push([cursor, o.inicio]);
    if (o.fim > cursor) cursor = o.fim;
  }
  if (cursor < fechamento) janelas.push([cursor, fechamento]);

  const livres = janelas.filter(([ini, fim]) => fim.diff(ini, 'minutes').minutes >= menorDuracao);
  const rotulo = `${dia.setLocale('pt-BR').toFormat('cccc, dd/MM')} (${dia.toFormat('yyyy-MM-dd')})`;
  linhas.push(`- ${rotulo}: ${livres.length ? livres.map(([ini, fim]) => `${hora(ini)}–${hora(fim)}`).join(', ') : 'sem horários livres'}`);
}

const horariosLivres = agendaConsultada
  ? linhas.join('\n')
  : 'INDISPONÍVEL — não foi possível consultar a agenda agora.';

return [{
  json: {
    lista_servicos: $('Formatar Lista de Serviços').first().json.lista_servicos,
    horarios_livres: horariosLivres,
    agenda_consultada: agendaConsultada
  }
}];

const ZONA = 'America/Sao_Paulo';
const agora = DateTime.now().setZone(ZONA);
const linhas = $input.all().map(i => i.json);

// Se a leitura da planilha falhou, o node devolve { error } — a IA não pode contar com a lista.
const planilhaConsultada = !linhas.some(r => r.error);

// Mesmo critério do Identificar Agendamento Escolhido: ativo e ainda no futuro.
const ativos = linhas
  .map(r => ({ ...r, inicio: DateTime.fromISO(String(r.data ?? ''), { zone: ZONA }) }))
  .filter(r => r.event_id && ['agendado', 'remarcado'].includes(r.status) && r.inicio.isValid && r.inicio > agora)
  .sort((a, b) => a.inicio - b.inicio);

const agendamentosAtivos = !planilhaConsultada
  ? 'INDISPONÍVEL — não foi possível consultar os agendamentos agora.'
  : ativos.length
    ? ativos.map(r => `- [${r.event_id}] ${r.servico} — ${r.inicio.setLocale('pt-BR').toFormat("cccc, dd/MM (yyyy-MM-dd) 'às' HH:mm")} — para: ${String(r.beneficiario ?? '').trim() || 'não informado'}`).join('\n')
    : 'Nenhum agendamento ativo para este telefone.';

return [{
  json: {
    ...$('Calcular Horários Livres').first().json,
    agendamentos_ativos: agendamentosAtivos
  }
}];

