return $input.all().map(item => {
  const output = item.json.output || {};
  const suspeito = /confirmad[oa]|marcad[oa]|reservad[oa]|agendad[oa]/i;

  if (output.intencao === 'duvida' && suspeito.test(output.confirmacao_texto || '')) {
    if (output.data_hora_inicio) {
      return { json: { ...item.json, output: { ...output, intencao: 'agendar' } } };
    }

    return {
      json: {
        ...item.json,
        output: {
          ...output,
          confirmacao_texto: 'Pode me confirmar o dia e o horário exatos que você gostaria? Assim eu já verifico a disponibilidade certinho.'
        }
      }
    };
  }

  return item;
});

const nome = $('Normalizar Dados da Mensagem').item.json.nome || '';

const diasSemana = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];
const meses = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];

const formatarDataHora = (iso) => {
  const dt = DateTime.fromISO(iso, { zone: 'America/Sao_Paulo' });
  if (!dt.isValid) return iso;
  const dia = diasSemana[dt.weekday % 7];
  const mes = meses[dt.month - 1];
  const hora = dt.minute === 0 ? `${dt.toFormat('H')}h` : `${dt.toFormat('H')}h${dt.toFormat('mm')}`;
  return `${dia}, dia ${dt.day} de ${mes}, às ${hora}`;
};

// Só o que ainda vai acontecer: um "agendado" de hoje cedo que já passou não é mais "marcado".
const agora = DateTime.now().setZone('America/Sao_Paulo');
const ativos = $input.all()
  .map(i => i.json)
  .filter(row => row.status === 'agendado' || row.status === 'remarcado')
  .filter(row => row.data && DateTime.fromISO(String(row.data), { zone: 'America/Sao_Paulo' }) > agora)
  .sort((a, b) => new Date(a.data) - new Date(b.data));

// Para quem é, quando não é o próprio cliente.
const para = a => {
  const b = String(a.beneficiario ?? '').trim();
  return b && b.toLowerCase() !== 'eu mesmo' ? ` (para ${b})` : '';
};

let mensagem_consulta;

if (ativos.length === 0) {
  const opcoes = [
    `Não encontrei nenhum agendamento ativo no momento` + (nome ? `, ${nome}` : '') + `. Quer marcar um horário?`,
    (nome ? `${nome}, não` : `Não`) + ` achei nenhum horário marcado aqui pra você agora. Vamos agendar um?`
  ];
  mensagem_consulta = opcoes[Math.floor(Math.random() * opcoes.length)];
} else if (ativos.length === 1) {
  const a = ativos[0];
  const opcoes = [
    `Tem sim` + (nome ? `, ${nome}` : '') + `! Seu ${a.servico || 'horário'}${para(a)} está marcado para ${formatarDataHora(a.data)}.`,
    `Confirmado aqui` + (nome ? `, ${nome}` : '') + `: ${a.servico || 'seu horário'}${para(a)} ${formatarDataHora(a.data)}.`
  ];
  mensagem_consulta = opcoes[Math.floor(Math.random() * opcoes.length)];
} else {
  const itens = ativos.map(a => `- ${a.servico || 'horário'}${para(a)} em ${formatarDataHora(a.data)}`).join('\n');
  mensagem_consulta = `Você tem ${ativos.length} agendamentos ativos` + (nome ? `, ${nome}` : '') + `:\n${itens}`;
}

return [{ json: { mensagem_consulta } }];

const ZONA = 'America/Sao_Paulo';
const normalizar = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const servicos = $('Buscar Serviços e Preços').all().map(i => i.json);

// Acha um serviço da planilha pelo nome: igual (ignorando acento/caixa) ou, se só um bater, parcial.
const encontrarServico = nome => {
  const alvo = normalizar(nome);
  if (!alvo) return null;
  const exato = servicos.find(s => normalizar(s.servico) === alvo);
  if (exato) return exato;
  const parciais = servicos.filter(s => normalizar(s.servico).includes(alvo) || alvo.includes(normalizar(s.servico)));
  return parciais.length === 1 ? parciais[0] : null;
};

// Duração em minutos pela planilha de Serviços; combinações ("X e Y") somam as partes.
const duracaoDoServico = nome => {
  if (!nome || normalizar(nome) === 'nao especificado') return null;
  const unico = encontrarServico(nome);
  if (unico) return Number(unico.duracao_minutos) || null;
  const partes = normalizar(nome).split(/\s*(?:\+|,| e )\s*/).filter(Boolean);
  if (partes.length < 2) return null;
  const encontrados = partes.map(encontrarServico);
  if (encontrados.some(s => !s || !Number(s.duracao_minutos))) return null;
  return encontrados.reduce((total, s) => total + Number(s.duracao_minutos), 0);
};

return $input.all().map((item, index) => {
  const output = { ...(item.json.output || {}) };
  const inicio = DateTime.fromISO(output.data_hora_inicio, { zone: ZONA });
  const duracao = duracaoDoServico(output.servico);

  // O término sai sempre de início + duração da planilha; o data_hora_fim da IA só fica se o serviço não for achado.
  if (duracao && inicio.isValid) {
    output.data_hora_fim = inicio.plus({ minutes: duracao }).toFormat("yyyy-MM-dd'T'HH:mm:ssZZ");
  }
  const fim = DateTime.fromISO(output.data_hora_fim, { zone: ZONA });

  const abertura = 9 * 60;
  const fechamento = 18 * 60;
  const minutosInicio = inicio.hour * 60 + inicio.minute;
  const minutosFim = fim.hour * 60 + fim.minute;
  const domingo = inicio.weekday === 7;
  const jaPassou = inicio.isValid && inicio < DateTime.now().setZone(ZONA);

  const dentroDoExpediente =
    inicio.isValid &&
    fim.isValid &&
    !domingo &&
    !jaPassou &&
    minutosInicio >= abertura &&
    minutosInicio < fechamento &&
    minutosFim <= fechamento;

  return {
    json: { ...item.json, output, duracao_minutos: duracao, duracao_fonte: duracao ? 'planilha' : 'ia', dentro_do_expediente: dentroDoExpediente },
    pairedItem: { item: index }
  };
});

const ZONA = 'America/Sao_Paulo';
const ACAO = 'remarcar';
const agora = DateTime.now().setZone(ZONA);
const saida = $('Interpretar Intenção do Cliente').first().json.output || {};
const alvo = String(saida.agendamento_alvo ?? '').trim();

// Só agendamentos ativos e ainda no futuro (o status já vem filtrado pelo node anterior).
const ativos = $input.all()
  .map((item, index) => ({ linha: item.json, index, inicio: DateTime.fromISO(String(item.json.data ?? ''), { zone: ZONA }) }))
  .filter(a => a.linha.event_id && a.inicio.isValid && a.inicio > agora)
  .sort((a, b) => a.inicio - b.inicio);

// Nunca adivinha: só segue com o agendamento que a IA identificou pelo id, ou com o único que existe.
const escolhido = ativos.find(a => a.linha.event_id === alvo) || (ativos.length === 1 ? ativos[0] : null);
if (escolhido) {
  return [{ json: { ...escolhido.linha, agendamentos_ativos: ativos.length }, pairedItem: { item: escolhido.index } }];
}
if (!ativos.length) {
  return [{ json: { agendamentos_ativos: 0 }, pairedItem: { item: 0 } }];
}

// Mais de um ativo e nenhum identificado: pergunta qual, listando os agendamentos reais.
const hora = dt => dt.toFormat(dt.minute ? "H'h'mm" : "H'h'");
const dia = dt => {
  const diferenca = dt.startOf('day').diff(agora.startOf('day'), 'days').days;
  if (diferenca === 0) return 'hoje';
  if (diferenca === 1) return 'amanhã';
  const artigo = dt.weekday >= 6 ? 'no' : 'na';
  return `${artigo} ${dt.setLocale('pt-BR').toFormat("cccc, 'dia' d 'de' LLLL")}`;
};
const quando = dt => {
  const d = dia(dt);
  return d === 'hoje' || d === 'amanhã' ? `${d} às ${hora(dt)}` : `${d}, às ${hora(dt)}`;
};
const juntar = (partes, separador) => partes.length === 1 ? partes[0] : `${partes.slice(0, -1).join(separador)} e ${partes[partes.length - 1]}`;
// Para quem é, quando não é o próprio cliente — ajuda a distinguir agendamentos parecidos.
const para = a => {
  const b = String(a.linha.beneficiario ?? '').trim();
  return b && b.toLowerCase() !== 'eu mesmo' ? ` (para ${b})` : '';
};
const quantidade = { 2: 'dois', 3: 'três', 4: 'quatro', 5: 'cinco' }[ativos.length] || String(ativos.length);
const mesmoDia = ativos.every(a => a.inicio.hasSame(ativos[0].inicio, 'day'));

const lista = mesmoDia
  ? `Você tem ${quantidade} agendamentos ${dia(ativos[0].inicio)}: ${juntar(ativos.map(a => `${a.linha.servico}${para(a)} às ${hora(a.inicio)}`), ', ')}`
  : `Você tem ${quantidade} agendamentos ativos: ${juntar(ativos.map(a => `${a.linha.servico}${para(a)} ${quando(a.inicio)}`), '; ')}`;
const perguntaPadrao = `${lista} — qual deles você quer ${ACAO}?`;

// A pergunta da IA (que fica na memória da conversa) é usada quando ela de fato perguntou;
// se o texto dela parecer uma ação já feita ou trouxer data numérica, vai a pergunta montada aqui.
const textoIA = String(saida.confirmacao_texto ?? '');
const pareceAcaoFeita = /cancelei|cancelad[oa]|remarquei|remarcad[oa]|desmarquei|desmarcad[oa]/i.test(textoIA);
const dataNumerica = /\b\d{1,2}\/\d{1,2}\b/.test(textoIA);
const mensagemEscolha = textoIA.includes('?') && !pareceAcaoFeita && !dataNumerica ? textoIA : perguntaPadrao;

return [{
  json: { agendamentos_ativos: ativos.length, precisa_escolher: true, mensagem_escolha: mensagemEscolha, pergunta_padrao: perguntaPadrao },
  pairedItem: { item: 0 }
}];

